#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

extern int dominant_eig2(const double *a, int n, double *lr, double *li, double *vout);

static PyObject *py_solve(PyObject *self, PyObject *args)
{
    PyObject *obj;
    int n;
    if (!PyArg_ParseTuple(args, "Oi", &obj, &n))
        return NULL;
    if (n <= 0 || n > 16)
        Py_RETURN_NONE;

    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!arr)
        return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != n || PyArray_DIM(arr, 1) != n) {
        Py_DECREF(arr);
        Py_RETURN_NONE;
    }

    npy_intp dims[1] = {n};
    PyArrayObject *out = (PyArrayObject *)PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
    if (!out) {
        Py_DECREF(arr);
        return NULL;
    }

    double lr = 0.0, li = 0.0;
    int rc = dominant_eig2((const double *)PyArray_DATA(arr), n, &lr, &li,
                           (double *)PyArray_DATA(out));
    Py_DECREF(arr);
    if (rc != 0) {
        Py_DECREF(out);
        Py_RETURN_NONE;
    }

    PyObject *lam = PyComplex_FromDoubles(lr, li);
    if (!lam) {
        Py_DECREF(out);
        return NULL;
    }
    PyObject *res = PyTuple_Pack(2, lam, (PyObject *)out);
    Py_DECREF(lam);
    Py_DECREF(out);
    return res;
}

static PyMethodDef methods[] = {
    {"solve", py_solve, METH_VARARGS, "dominant eigenpair"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_domfast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit__domfast(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}
EOF
